import { CONSTANTS, isNonEmptyString, wrapValidatorsWithPromise } from '@zcatalyst/utils';
import { CatalystCacheError } from './utils/error';
const { REQ_METHOD, COMPONENT, CREDENTIAL_USER } = CONSTANTS;
export class Segment {
    constructor(cacheInstance, segmentDetails) {
        this.requester = cacheInstance.requester;
        const segmentId = parseInt(segmentDetails.id + '');
        this.id = isNaN(segmentId) ? null : segmentDetails.id + '';
        this.segmentName = isNonEmptyString(segmentDetails.segment_name)
            ? segmentDetails.segment_name
            : null;
    }
    getComponentName() {
        return COMPONENT.cache;
    }
    async put(key, value, expiry) {
        await wrapValidatorsWithPromise(() => {
            isNonEmptyString(key, 'cache_key', true);
        }, CatalystCacheError);
        const apiUrl = this.id === null ? '/cache' : `/segment/${this.id}/cache`;
        const postData = {
            cache_name: key,
            cache_value: value,
            expiry_in_hours: expiry ? expiry : null
        };
        const request = {
            method: REQ_METHOD.post,
            type: "json",
            data: postData,
            path: apiUrl,
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.admin
        };
        const response = await this.requester.send(request);
        return response.data.data;
    }
    async update(key, value, expiry) {
        await wrapValidatorsWithPromise(() => {
            isNonEmptyString(key, 'cache_key', true);
        }, CatalystCacheError);
        const apiUrl = this.id === null ? '/cache' : `/segment/${this.id}/cache`;
        const postData = {
            cache_name: key,
            cache_value: value,
            expiry_in_hours: expiry ? expiry : null
        };
        const request = {
            method: REQ_METHOD.put,
            type: "json",
            data: postData,
            path: apiUrl,
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.admin
        };
        const response = await this.requester.send(request);
        return response.data.data;
    }
    async getValue(cacheKey) {
        const cacheObj = await this.get(cacheKey);
        return cacheObj.cache_value;
    }
    async get(cacheKey) {
        await wrapValidatorsWithPromise(() => {
            isNonEmptyString(cacheKey, 'cache_key', true);
        }, CatalystCacheError);
        const apiUrl = this.id === null ? '/cache' : `/segment/${this.id}/cache`;
        const query = { cacheKey };
        const request = {
            method: REQ_METHOD.get,
            path: apiUrl,
            qs: query,
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.admin
        };
        const response = await this.requester.send(request);
        return response.data.data;
    }
    async delete(cacheKey) {
        await wrapValidatorsWithPromise(() => {
            isNonEmptyString(cacheKey, 'cache_key', true);
        }, CatalystCacheError);
        const apiUrl = this.id === null ? '/cache' : `/segment/${this.id}/cache`;
        const query = { cacheKey };
        const request = {
            method: REQ_METHOD.delete,
            path: apiUrl,
            qs: query,
            service: "baas",
            track: true,
            user: CREDENTIAL_USER.admin
        };
        await this.requester.send(request);
        return true;
    }
    toString() {
        return JSON.stringify(this.toJSON());
    }
    toJSON() {
        return {
            id: this.id,
            segment_name: this.segmentName
        };
    }
}
